pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // Establish caller as the current owner so transferOwnership is the exercised entry point.
        vm.prank(address(this));
        c = new C();
        // Make the fuzzed caller the owner of a fresh contract via the reference path:
        // deploy again with vm.prank is not possible for constructor, so transfer ownership first.
        // Simpler: set owner through the reference behaviour of the contract under test itself.
        // owner starts as address(this); prank as this to transfer to fuzzed caller.
        vm.prank(address(this));
        c.transferOwnership(caller);
        vm.assume(newOwner != caller);

        // Rule: when the current owner calls transferOwnership(newOwner), owner becomes newOwner;
        // when a non-owner calls it, owner is unchanged. (Reference satisfies both for all inputs.)
        vm.prank(caller);
        c.transferOwnership(newOwner);

        // Reference: owner == newOwner (caller was owner). Mutant: call reverts or, if caller was
        // non-owner, arbitrary updates happen; either way the mutant's owner differs for some input.
        assertTrue(c.owner() == newOwner);
    }
}

