import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        address oldOwner = c.owner();
        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(
            ok == (caller == oldOwner) && (!ok || c.owner() == newOwner),
            "transferOwnership must be callable only by the current owner and set owner to newOwner"
        );
    }
}

