pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // wide admissible domain: any actor, any new owner (self-transfers included)
        address oldOwner = c.owner();

        bool ok;
        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after the attempt, the owner is newOwner exactly when
        // the current owner successfully transferred; a call by anyone else
        // must not leave the contract owned by newOwner.
        if (ok) {
            assertTrue(actor == oldOwner && c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == oldOwner);
        }
    }
}

