// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address constant INITIAL_OWNER = address(0);

    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        // current owner is address(0); it transfers ownership to newOwner
        vm.prank(INITIAL_OWNER);
        c.transferOwnership(newOwner);

        vm.prank(caller);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: owned() succeeds exactly for the current owner
        assertTrue(ok == (caller == c.owner()));
    }
}
